22	export interface StageContext {
23	  run: RunRecord;
24	  dataDir: string;
25	  runDir: string;
26	  read<T>(stage: StageName): T; // artifact of a completed stage; throws if absent
27	  log(message: string): void; // appends an event
28	  feedback: string | null; // reason passed by the last loop-back, if any
29	}
30	
31	export interface StageResult<T> {
32	  artifact: T;
33	  loopBackTo?: StageName;
34	  reason?: string;
35	  final?: { status: 'needs_approval' | 'blocked'; reason: string };
36	}
37	
38	export interface Stage<T = unknown> {
39	  name: StageName;
40	  maxAttempts: number;
41	  run(ctx: StageContext): Promise<StageResult<T>>;
42	}
