];

function stubStages(calls: Record<string, number>): Stage[] {
  return ALL_STAGE_NAMES.map((name) => ({
    name,
    maxAttempts: 1,
    run: async () => {
      calls[name] = (calls[name] ?? 0) + 1;
      return { artifact: { name } };
    },
  }));
