import { loadEnv } from '@dailies/core';
import { openDb } from '@dailies/pipeline';
import type { Database } from '@dailies/pipeline';
import { ensureWebTables } from './store';

let cached: { path: string; db: Database } | null = null;

export function getDataDir(): string {
  return loadEnv().dataDir;
}

export function getDb(): Database {
  const dataDir = getDataDir();
  const path = join(dataDir, 'dailies.db');
  if (cached?.path !== path) {
    mkdirSync(dataDir, { recursive: true });
    const db = openDb(path);
    ensureWebTables(db);
    cached = { path, db };
  }
  return cached.db;
}

export function parseRepoUrl(input: string): string | null {
  let url: URL;
  try {
    url = new URL(input);
  } catch {
    return null;
  }
  if (url.protocol !== 'https:' || url.hostname !== 'github.com') return null;
  if (url.search || url.hash) return null;

  const path = url.pathname.replace(/\/+$/, '');
  const match = /^\/([A-Za-z0-9._-]+)\/([A-Za-z0-9._-]+?)(\.git)?$/.exec(path);
  if (!match) return null;

  return `https://github.com/${match[1]}/${match[2]}${match[3] ?? ''}`;
}

const HOURS = /^(\d+)h$/;
const DAYS = /^(\d+)d$/;

export function parseSince(input: string, now: Date): string | null {
  const hours = HOURS.exec(input);
  if (hours) return new Date(now.getTime() - Number(hours[1]) * 60 * 60 * 1000).toISOString();

  const days = DAYS.exec(input);
  if (days) return new Date(now.getTime() - Number(days[1]) * 24 * 60 * 60 * 1000).toISOString();

  const parsed = new Date(input);
  if (Number.isNaN(parsed.getTime())) return null;
  return parsed.toISOString();
}

export const RUN_ID_PATTERN = /^run_[0-9a-f]+$/;
export const MEDIA_FILES = new Set(['reel.mp4', 'reel.srt', 'poster.png']);

import { isIP } from 'node:net';

export function clientIp(request: Request): string {
  const xff = request.headers.get('x-forwarded-for');
  const first = xff?.split(',')[0]?.trim();
  return first && isIP(first) ? first : 'unknown';
}

import type { Database, StageName } from '@dailies/pipeline';

export const STAGE_ORDER: StageName[] = [
  'ingest',
  'edit',
  'verify',
  'script',
  'ground',
  'voice',
  'render',
  'review',
  'gate',
];

export interface StageInfo {
  name: StageName;
  status: string;
  attempt: number;
  startedAt: string | null;
  endedAt: string | null;
  error: string | null;
}

export function listStages(db: Database, runId: string): StageInfo[] {
  const rows = db
    .prepare('SELECT name, status, attempt, started_at as startedAt, ended_at as endedAt, error FROM stages WHERE run_id = ?')
    .all(runId) as StageInfo[];
  const byName = new Map(rows.map((r) => [r.name, r]));

  return STAGE_ORDER.map(
    (name) =>
      byName.get(name) ?? { name, status: 'pending', attempt: 0, startedAt: null, endedAt: null, error: null },
  );
}

export function isStageDoneWeb(db: Database, runId: string, name: StageName): boolean {
  const row = db.prepare('SELECT status FROM stages WHERE run_id = ? AND name = ?').get(runId, name) as
    | { status: string }
    | undefined;
  return row?.status === 'done';
}

import { NextResponse } from 'next/server';
import { loadEnv, DEFAULT_BUDGET } from '@dailies/core';
import { createRun } from '@dailies/pipeline';
import { getDb } from '../../../server/db';
import { allowRun } from '../../../server/store';
import { clientIp } from '../../../server/client-ip';
import { parseRepoUrl, parseSince } from '../../../server/validate';

export async function POST(request: Request): Promise<Response> {
  loadEnv();
  let body: { repoUrl?: unknown; since?: unknown };
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: 'invalid JSON body' }, { status: 400 });
  }

  if (typeof body.repoUrl !== 'string') {
    return NextResponse.json({ error: 'repoUrl is required' }, { status: 400 });
  }
  const repoUrl = parseRepoUrl(body.repoUrl);
  if (!repoUrl) {
    return NextResponse.json({ error: 'repoUrl must be https://github.com/<owner>/<repo>' }, { status: 400 });
  }

  const now = new Date();
  const sinceInput = typeof body.since === 'string' ? body.since : '7d';
  const since = parseSince(sinceInput, now);
  if (!since) {
    return NextResponse.json({ error: 'since must be <n>h, <n>d or an ISO date' }, { status: 400 });
  }

  const db = getDb();
  const ip = clientIp(request);
  const limits = {
    perIpPerDay: Number(process.env.DAILIES_RUNS_PER_IP ?? 3),
    globalPerDay: Number(process.env.DAILIES_RUNS_PER_DAY ?? 40),
  };
  const allowed = allowRun(db, ip, now, limits);
  if (!allowed.ok) {
    return NextResponse.json({ error: 'rate limited', reason: allowed.reason }, { status: 429 });
  }

  const runId = createRun(db, { repoUrl, since, until: now.toISOString(), budget: DEFAULT_BUDGET });
  return NextResponse.json({ runId }, { status: 201 });
}

import { NextResponse } from 'next/server';
import { getRun } from '@dailies/pipeline';
import { getDb } from '../../../../server/db';
import { listStages } from '../../../../server/stages';

export async function GET(
  _request: Request,
  { params }: { params: Promise<{ id: string }> },
): Promise<Response> {
  const { id } = await params;
  const db = getDb();

  let run;
  try {
    run = getRun(db, id);
  } catch {
    return NextResponse.json({ error: 'run not found' }, { status: 404 });
  }

  const stages = listStages(db, id);
  return NextResponse.json({ run, stages }, { status: 200 });
}

import { getRun, listEvents } from '@dailies/pipeline';
import type { Database } from '@dailies/pipeline';

const POLL_MS = 1000;

export function createEventStream(
  db: Database,
  runId: string,
  afterId: number,
  signal: AbortSignal,
): ReadableStream<Uint8Array> {
  const encoder = new TextEncoder();
  let lastId = afterId;
  let timer: ReturnType<typeof setTimeout> | null = null;

  return new ReadableStream<Uint8Array>({
    start(controller) {
      const stop = () => {
        if (timer !== null) clearTimeout(timer);
        timer = null;
      };

      const tick = () => {
        if (signal.aborted) {
          stop();
          return;
        }

        let status: string;
        try {
          for (const event of listEvents(db, runId, lastId)) {
            lastId = event.id;
            controller.enqueue(encoder.encode(`id: ${event.id}\nevent: message\ndata: ${JSON.stringify(event)}\n\n`));
          }
          status = getRun(db, runId).status;
        } catch (err) {
          stop();
          controller.error(err);
          return;
        }

        if (status !== 'running') {
          controller.enqueue(encoder.encode('event: done\ndata: {}\n\n'));
          stop();
          controller.close();
          return;
        }

        timer = setTimeout(tick, POLL_MS);
      };

      signal.addEventListener('abort', () => {
        stop();
        try {
          controller.close();
        } catch {
          // already closed
        }
      });

      tick();
    },
    cancel() {
      if (timer !== null) clearTimeout(timer);
      timer = null;
    },
  });
}

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
